final class TokenRegistry[T] {
  private val registry: mutable.Map[String, TokenContainer[T]] = mutable.Map.empty
  private val handlers: mutable.ListBuffer[T => Option[Token]] = mutable.ListBuffer.empty

  def register(key: String, container: TokenContainer[T]): Unit = registry.update(key, container)

  def addHandler(handler: T => Option[Token]): Unit = handlers += handler

  def process(key: String): List[Option[Token]] = {
    registry.get(key) match {
      case None => Nil
      case Some(container) =>
        container.getAll.toList.map { item =>
          handlers.iterator.flatMap(h => h(item).iterator).take(1).toList.headOption
        }
    }
  }
}

